+func (g *WireCodeGenerator) generateFieldsOf(sb *strings.Builder) {
+	if len(g.types) == 0 {
+		return
+	}
+
+	t := g.types[g.rand.Intn(len(g.types))]
+	if len(t.fields) == 0 {
+		return
+	}
