+	// Select some fields
+	numFields := g.rand.Intn(len(t.fields)) + 1
+	fieldNames := make([]string, 0, numFields)
+	for i := 0; i < numFields && i < len(t.fields); i++ {
+		fieldNames = append(fieldNames, fmt.Sprintf("\"%s\"", t.fields[i].name))
+	}
