+		},
+		// Nested NewSet reference (valid but complex)
+		func(sb *strings.Builder) {
+			sb.WriteString("var InnerSet = wire.NewSet()\n\n")
+			sb.WriteString("var OuterSet = wire.NewSet(InnerSet)\n\n")
+		},
+		// Deeply nested sets
+		func(sb *strings.Builder) {
