+		wantImports   map[string]string
+		name          string
+	}{
+		{
+			name:          "nil expression",
+			expr:          nil,
+			sourceImports: map[string]string{"pkg": "example.com/pkg"},
+			wantImports:   map[string]string{},
+		},
+		{
+			name:          "simple identifier (no package)",
+			expr:          ast.NewIdent("Foo"),
+			sourceImports: map[string]string{"pkg": "example.com/pkg"},
+			wantImports:   map[string]string{},
+		},
