+			name:        "nil pattern",
+			pattern:     nil,
+			wantImports: []string{},
+		},
+		{
+			name: "KessokuProvide with package reference",
+			pattern: &KessokuProvide{
+				FuncExpr: &ast.SelectorExpr{
+					X:   ast.NewIdent("pkg"),
+					Sel: ast.NewIdent("NewFoo"),
+				},
+			},
+			wantImports: []string{"example.com/pkg"},
+		},
+		{
+			name: "KessokuSet with nested providers",
+			pattern: &KessokuSet{
