+				Args: []ast.Expr{},
+			},
+			wantNil: true,
+		},
+	}
+
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			got := p.extractTypeFromNew(tt.expr, info)
+			if tt.wantNil && got != nil {
+				t.Errorf("extractTypeFromNew() = %v, want nil", got)
+			}
+			if !tt.wantNil && got == nil {
+				t.Errorf("extractTypeFromNew() = nil, want non-nil")
+			}
+		})
