+
+// NewTypeConverter creates a new TypeConverter for the given package.
+func NewTypeConverter(currentPkg *types.Package) *TypeConverter {
+	return &TypeConverter{
+		currentPkg: currentPkg,
+		imports:    make(map[string]string),
+	}
